/*
 * Paper style: warm paper surfaces, serif titles, pill controls, soft shadows and pastel accents.
 * Switched at runtime with data-style="paper" on <html> (no attribute = the default style); the attribute
 * also works on any element to give one section the style. Light and dark both apply.
 * Import after the theme (and after theme-accents.css when you use it).
 */

html[data-style="paper"],
[data-style="paper"] {
  /* Titles take the text serif; body text stays on --font-sans. */
  --heading-font: "Source Serif 4 Variable", "Source Serif 4", "Noto Serif SC Variable", "Noto Serif SC", ui-serif, Georgia, "Songti SC", serif;
  --heading-font-features: normal;
  /* Controls (buttons, tabs, segmented, toggles) turn into pills; every other radius stays on the scale. */
  --control-radius: 2rem;
  --background: oklch(98.4% 0.006 78);
  --card: oklch(99.6% 0.003 78);
  --popover: oklch(99.6% 0.003 78);
  --surface-sunken: oklch(30% 0.03 60 / 0.05);
  --surface-standout: oklch(26% 0.012 60);
  --standout-foreground: oklch(97.5% 0.008 78);
  --foreground: oklch(23% 0.014 60);
  --card-foreground: oklch(23% 0.014 60);
  --popover-foreground: oklch(23% 0.014 60);
  --muted-foreground: oklch(24% 0.02 60 / 0.68);
  --fg-tertiary: oklch(26% 0.02 60 / 0.5);
  --fg-disabled: oklch(28% 0.02 60 / 0.34);
  --secondary: oklch(30% 0.03 60 / 0.065);
  --secondary-foreground: oklch(23% 0.014 60);
  --muted: oklch(30% 0.03 60 / 0.065);
  --accent: oklch(30% 0.03 60 / 0.1);
  --accent-foreground: oklch(23% 0.014 60);
  --border: oklch(30% 0.03 60 / 0.12);
  --border-subtle: oklch(30% 0.03 60 / 0.05);
  --border-strong: oklch(30% 0.03 60 / 0.2);
  --input: oklch(30% 0.03 60 / 0.14);
  --code: oklch(97% 0.007 78);
  --scrollbar: oklch(30% 0.03 60 / 0.18);
  --scrollbar-hover: oklch(30% 0.03 60 / 0.3);
  --shell: oklch(96.2% 0.009 76);
  --shell-border: oklch(30% 0.03 60 / 0.1);
  --shadow-border: 0 0 0 1px oklch(30% 0.03 60 / 0.1);
  --shadow-default: 0 0 0 1px oklch(30% 0.03 60 / 0.075), 0 1px 2px oklch(30% 0.03 60 / 0.05), 0 4px 14px -4px oklch(30% 0.03 60 / 0.08);
  --shadow-lg: 0 0 0 1px oklch(30% 0.03 60 / 0.07), 0 4px 10px -3px oklch(30% 0.03 60 / 0.07), 0 18px 40px -10px oklch(30% 0.03 60 / 0.14);
  --shadow-xl: 0 0 0 1px oklch(30% 0.03 60 / 0.06), 0 12px 28px -8px oklch(30% 0.03 60 / 0.1), 0 32px 72px -16px oklch(30% 0.03 60 / 0.2);
  --skeuo-raised: var(--shadow-default);
  --skeuo-raised-hover: 0 0 0 1px oklch(30% 0.03 60 / 0.12), 0 2px 4px oklch(30% 0.03 60 / 0.06), 0 8px 20px -6px oklch(30% 0.03 60 / 0.12);
  --skeuo-pressed: var(--shadow-border);
  --skeuo-primary: 0 1px 2px oklch(30% 0.03 60 / 0.1), 0 4px 12px -4px oklch(30% 0.03 60 / 0.14);
  --skeuo-well: inset 0 0 0 1px var(--input);
  --skeuo-surface: var(--shadow-lg);
  --skeuo-chip: var(--shadow-border);
  --image-outline: oklch(30% 0.03 60 / 0.1);
  --destructive: oklch(60% 0.165 30);
  --destructive-hover: oklch(56% 0.165 30);
  --destructive-foreground: oklch(99% 0.004 78);
  --destructive-subtle: oklch(60% 0.165 30 / 0.11);
  --destructive-border: oklch(60% 0.165 30 / 0.3);
  --success: oklch(60% 0.115 155);
  --success-hover: oklch(56% 0.115 155);
  --success-foreground: oklch(99% 0.004 78);
  --success-subtle: oklch(60% 0.115 155 / 0.11);
  --success-border: oklch(60% 0.115 155 / 0.3);
  --warning: oklch(66% 0.15 52);
  --warning-hover: oklch(62% 0.15 52);
  --warning-foreground: oklch(99% 0.004 78);
  --warning-subtle: oklch(66% 0.15 52 / 0.11);
  --warning-border: oklch(66% 0.15 52 / 0.3);
}

/* Softer corners by default; a radius preset or a custom value still wins. */
html[data-style="paper"]:not([data-radius]),
html:not([data-radius]) [data-style="paper"]:not([data-radius]) {
  --radius: 0.75rem;
}

html[data-style="paper"].dark,
