  --fg-tertiary: oklch(97% 0.018 80 / 0.44);
  --fg-disabled: oklch(97% 0.018 80 / 0.32);
  --secondary: oklch(97% 0.018 80 / 0.075);
  --secondary-foreground: oklch(94% 0.012 80);
  --muted: oklch(97% 0.018 80 / 0.075);
  --accent: oklch(97% 0.018 80 / 0.11);
