  --shadow-border: 0 0 0 1px oklch(97% 0.018 80 / 0.1);
  --shadow-default: 0 0 0 1px oklch(97% 0.018 80 / 0.085) inset, 0 1px 2px oklch(0% 0 0 / 0.2), 0 6px 16px -6px oklch(0% 0 0 / 0.35);
  --shadow-lg: 0 0 0 1px oklch(97% 0.018 80 / 0.12), 0 4px 10px -3px oklch(0% 0 0 / 0.3), 0 18px 40px -10px oklch(0% 0 0 / 0.5);
  --shadow-xl: 0 0 0 1px oklch(97% 0.018 80 / 0.1) inset, 0 12px 28px -8px oklch(0% 0 0 / 0.35), 0 32px 72px -16px oklch(0% 0 0 / 0.6);
  --skeuo-raised: var(--shadow-default);
  --skeuo-raised-hover: 0 0 0 1px oklch(97% 0.018 80 / 0.14) inset, 0 2px 4px oklch(0% 0 0 / 0.25), 0 8px 20px -6px oklch(0% 0 0 / 0.4);
  --skeuo-pressed: var(--shadow-border);
  --skeuo-primary: 0 0 0 0 transparent;
  --skeuo-well: inset 0 0 0 1px var(--input);
  --skeuo-surface: var(--shadow-lg);
  --skeuo-chip: var(--shadow-border);
  --image-outline: oklch(97% 0.018 80 / 0.1);
  --destructive: oklch(72% 0.13 28);
  --destructive-hover: oklch(76% 0.13 28);
  --destructive-foreground: oklch(21% 0.02 28);
  --destructive-subtle: oklch(72% 0.13 28 / 0.14);
  --destructive-border: oklch(72% 0.13 28 / 0.32);
  --success: oklch(76% 0.1 155);
  --success-hover: oklch(80% 0.1 155);
  --success-foreground: oklch(21% 0.02 155);
  --success-subtle: oklch(76% 0.1 155 / 0.14);
  --success-border: oklch(76% 0.1 155 / 0.32);
  --warning: oklch(80% 0.12 62);
  --warning-hover: oklch(84% 0.12 62);
  --warning-foreground: oklch(21% 0.02 62);
  --warning-subtle: oklch(80% 0.12 62 / 0.14);
  --warning-border: oklch(80% 0.12 62 / 0.32);
}

/* Accents: dusty solids on paper, pastel solids with ink text in dark. Blue (no data-accent) is the default. */
html[data-style="paper"]:not([data-accent]),
[data-style="paper"]:not([data-accent]) {
  --primary: oklch(60% 0.14 252);
  --primary-hover: oklch(56% 0.14 252);
  --primary-active: oklch(50% 0.14 252);
  --primary-foreground: oklch(99% 0.004 78);
  --primary-subtle: oklch(62% 0.14 252 / 0.12);
  --primary-subtle-hover: oklch(62% 0.14 252 / 0.18);
  --primary-border: oklch(58% 0.14 252 / 0.32);
  --ring: oklch(58% 0.14 252 / 0.5);
}
html[data-style="paper"].dark:not([data-accent]),
.dark [data-style="paper"]:not([data-accent]) {
  --primary: oklch(80% 0.101 252);
  --primary-hover: oklch(84% 0.101 252);
  --primary-active: oklch(88% 0.101 252);
